async function handleShiftCheckin() {
    const btn = document.getElementById('btn-shift-checkin');
    btn.disabled = true;
    btn.innerHTML = ' Checking In...';

    try {
        // Get user's location
        let latitude = null;
        let longitude = null;

        if (navigator.geolocation) {
            try {
                const position = await new Promise((resolve, reject) => {
                    navigator.geolocation.getCurrentPosition(resolve, reject, {
                        enableHighAccuracy: true,
                        timeout: 10000,
                        maximumAge: 0
                    });
                });
                latitude = position.coords.latitude;
                longitude = position.coords.longitude;
            } catch (geoError) {
                console.warn('Could not get location:', geoError);
            }
        }

        // Call check-in API
        const response = await fetch('/guardpro/api/shift/checkin', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    shift_id: ,
                    latitude: latitude,
                    longitude: longitude
                }
            })
        });

        const result = await response.json();

        if (result.result && (result.result.success || !result.result.error)) {
            alert('Successfully checked in!');
            location.reload();
        } else {
            alert('Check-in failed: ' + (result.result?.error || result.result?.message || 'Unknown error'));
            btn.disabled = false;
            btn.innerHTML = ' Check In';
        }
    } catch (error) {
        console.error('Check-in error:', error);
        alert('Check-in failed: ' + error.message);
        btn.disabled = false;
        btn.innerHTML = ' Check In';
    }
}

